<script setup lang="ts">
import { computed, inject, onMounted, reactive, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage } from 'element-plus'
import CatalogOzonTabs from '../components/CatalogOzonTabs.vue'
import { api } from '../api'
import { sharedProductsPilot } from '../deployment'
import CodexHandoffPanel from '../components/CodexHandoffPanel.vue'
import type { CatalogProduct, Publication, Store } from '../types'

const currentUser=inject<any>('erpCurrentUser'),accountMode=inject<any>('erpAccountMode')
const canManage=computed(()=>accountMode?.value===false||currentUser?.value?.role==='admin')
const prefixDrafts=ref<Record<string,string>>({}),prefixSaving=ref('')
const targetStores=computed(()=>stores.value.filter(x=>form.store_ids.includes(x.id)))
async function savePrefix(store:Store){if(!canManage.value)return;prefixSaving.value=store.id;try{const result=await api.patch<Store>(`/stores/${store.id}`,{offer_prefix:(prefixDrafts.value[store.id]||'').trim()});stores.value=stores.value.map(x=>x.id===store.id?result:x);prefixDrafts.value[store.id]=result.offer_prefix||'';pricePreview.value=[];ElMessage.success('店铺前缀已保存，新上架任务使用该前缀')}catch(error:any){ElMessage.error(error?.message||'前缀保存失败')}finally{prefixSaving.value=''}}
const route=useRoute(),products=ref<CatalogProduct[]>([]),total=ref(0),page=ref(1),pageSize=ref(50),search=ref(''),source=ref(String(route.query.source||'pod')),productLoading=ref(false)
const selected=ref<Record<string,CatalogProduct>>({}),stores=ref<Store[]>([]),history=ref<Publication[]>([]),loading=ref(false),categories=ref<any[]>([]),categoryLoading=ref(false),categoryAttributes=ref<any[]>([]),attributeLoading=ref(false),detail=ref<Publication>(),drawer=ref(false),pricePreview=ref<any[]>([]),previewLoading=ref(false)
const chosenCategory=ref<any>()
const codexBatch=ref('')
const form=reactive<any>({completion_method:'api',codex_delivery:'api',store_ids:[],requirements_text:'',keywords_text:'',category_value:'',image_policy:'regenerate_main',custom_regenerate_roles:[],save_generated_to_catalog:false,submit_via_api:true,pricing_mode:'configured',price:undefined,old_price:undefined,additional_image_count:3,merge_mode:'single',merge_model_name:'',variant_attribute_ids:[],custom_pricing:false,pricing_overrides:{}})
const podCategory=ref(''),podCategories=ref<any[]>([]),podImageTemplate=ref<string[]>([])
const podSample=computed(()=>selectedProducts.value.find(x=>x.source_type==='pod'))
const individualImageProducts=computed(()=>selectedProducts.value.filter(x=>x.source_type!=='pod'))
const bulkSelecting=ref(false)
const pageFullySelected=computed(()=>products.value.length>0&&products.value.every(x=>!!selected.value[x.id]))
const pricingModules=ref<any[]>([]),storePricing=ref<any[]>([])
function originalPricing(key:string){const rows=storePricing.value.filter(x=>form.store_ids.includes(x.store_id));return rows.length?rows.map(x=>`${x.store_name}：${x.values[key]===''||x.values[key]==null?'未配置':x.values[key]}`).join('；'):'选择目标店铺后显示原有数值'}
const profitCategories=computed(()=>pricingModules.value.find(x=>x.name===form.pricing_overrides.pricing_category_module)?.categories||[])
const filterStore=ref(''),publicationState=ref(''),imageSelections=ref<Record<string,string[]>>({}),imageProduct=ref<any>(),imageRows=ref<any[]>([]),imageLoading=ref(false)
const pricingFields=[['target_cost_profit_margin','目标成本利润率（%）',10000],['pricing_advertising_rate','广告占比（%）',99.99],['pricing_return_rate','退货率（%）',99.99],['pricing_sticker_fee','贴单费（CNY）',100000],['pricing_operating_cost','固定运营费（CNY）',100000],['pricing_logistics_service_rate','物流服务费率（%）',99.99],['pricing_price_multiplier','售价倍率',100],['pricing_old_price_multiplier','划线价倍率',100]] as const
const imagePolicies=[['reuse','全部复用产品图库'],['regenerate_main','只重做主图'],['regenerate_additional','只重做附图'],['regenerate_all','主图和附图全部重做'],['custom','自定义重做']]
const selectedProducts=computed(()=>Object.values(selected.value)),canSaveGallery=computed(()=>form.store_ids.length===1),totalPages=computed(()=>Math.max(1,Math.ceil(total.value/pageSize.value)))
const sourceLabel:Record<string,string>={pod:'POD',follow:'OZON 跟卖',self_selected:'自主产品'}

const selectedVariantKeys=ref<string[]>([])
function activeVariants(product:any){return (product.variants||[]).filter((v:any)=>v.active!==false)}
function variantKey(v:any){const color=String(v.color||'').trim().toLowerCase(),size=String(v.size||'').trim().toLowerCase();return color||size?`${color}|${size}`:`spec|${String(v.specification||'').trim().toLowerCase()}`}
const variantOptions=computed(()=>{const options=new Map<string,any>();for(const p of selectedProducts.value)for(const v of activeVariants(p)){const key=variantKey(v);if(!options.has(key))options.set(key,{key,label:v.size||v.specification||'单一规格',color:v.color||'',matched:selectedProducts.value.filter(p=>activeVariants(p).some((v:any)=>variantKey(v)===key)).length})}return [...options.values()]})
const selectedVariantIds=computed(()=>selectedProducts.value.flatMap(p=>activeVariants(p).filter((v:any)=>selectedVariantKeys.value.includes(variantKey(v))).map((v:any)=>v.id)))
watch(()=>selectedProducts.value.map(p=>p.id).join(','),(_,previous)=>{if(!selectedProducts.value.length)selectedVariantKeys.value=[];else if(!previous)selectedVariantKeys.value=variantOptions.value.map(x=>x.key);pricePreview.value=[]})
function publicationSelection(){const hasVariants=selectedProducts.value.some(p=>activeVariants(p).length);if(hasVariants&&!selectedVariantIds.value.length)throw new Error('请至少选择一个本批上架规格');return {product_ids:selectedProducts.value.map(x=>x.id),...(hasVariants?{variant_ids:selectedVariantIds.value}:{})}}
function productQuery(current=page.value,size=pageSize.value){return new URLSearchParams({page:String(current),page_size:String(size),sort:'sku_desc',include_variants:'true',search:search.value,source_type:source.value,status:'ready',ozon_store_id:filterStore.value,ozon_state:publicationState.value,pod_category:source.value==='pod'?podCategory.value:''})}
async function loadProducts(){productLoading.value=true;try{const q=productQuery();const result=await api.get<any>(`/catalog/products?${q}`);products.value=result.items;total.value=result.total;podCategories.value=result.pod_category_options||[]}finally{productLoading.value=false}}
async function changeSource(){podCategory.value='';await queryProducts()}
async function queryProducts(){page.value=1;await loadProducts()}
function applyBatchSelection(rows:CatalogProduct[],remove=false){const next={...selected.value};for(const item of rows){if(remove)delete next[item.id];else next[item.id]=item}if(Object.keys(next).length>100){ElMessage.warning('每批最多选择100个产品，请缩小筛选范围或分批选择');return}selected.value=next;pricePreview.value=[]}
function togglePage(){applyBatchSelection(products.value,pageFullySelected.value)}
async function selectAllFiltered(){bulkSelecting.value=true;try{const result=await api.get<any>(`/catalog/products?${productQuery(1,100)}`);if(result.total>100)return ElMessage.warning('当前筛选超过100个产品，请按类目或搜索缩小范围后分批选择');applyBatchSelection(result.items||[])}finally{bulkSelecting.value=false}}
function toggleProduct(item:CatalogProduct){if(!selected.value[item.id]&&selectedProducts.value.length>=100)return ElMessage.warning('每批最多选择100个产品');const next={...selected.value};if(next[item.id])delete next[item.id];else next[item.id]=item;selected.value=next}
function removeSelected(id:string){const next={...selected.value};delete next[id];selected.value=next}
function clearSelected(){selected.value={};imageSelections.value={};podImageTemplate.value=[];imageRows.value=[];imageProduct.value=undefined}
async function changeStoreFilter(){publicationState.value=filterStore.value?'available':'';clearSelected();pricePreview.value=[];await queryProducts()}
let imageRequest=0
async function editImages(item:CatalogProduct){const request=++imageRequest;imageLoading.value=true;imageProduct.value=item;imageRows.value=[];try{const product=await api.get<any>(`/catalog/products/${item.id}`);if(request!==imageRequest)return;const rows=(product.assets||[]).filter((x:any)=>['main','mockup','additional','sku'].includes(x.role)&&String(x.asset?.oss_url||'').startsWith('https://')).sort((a:any,b:any)=>(Number(a.role!=='main')-Number(b.role!=='main'))||a.position-b.position);const saved=item.source_type==='pod'&&podImageTemplate.value.length?podImageTemplate.value.map(key=>rows.find((x:any)=>imageKey(x)===key)).filter(Boolean).map((x:any)=>x.asset_id||x.asset.id):imageSelections.value[item.id];const order=new Map((saved||[]).map((id,index)=>[id,index]));imageRows.value=rows.map((x:any,index:number)=>({id:x.asset_id||x.asset.id,url:x.asset.oss_url,name:x.asset.name||x.role,key:imageKey(x),included:saved?saved.includes(x.asset_id||x.asset.id):index<15})).sort((a:any,b:any)=>(order.get(a.id)??100)-(order.get(b.id)??100));syncImageSelection()}catch(error:any){if(request===imageRequest)ElMessage.error(error?.message||'图片读取失败')}finally{if(request===imageRequest)imageLoading.value=false}}
function imageKey(link:any){return String(link.asset?.name||link.asset?.oss_key||'').split(/[\\/]/).pop()||''}
function syncImageSelection(){if(!imageProduct.value)return;const rows=imageRows.value.filter(x=>x.included);if(imageProduct.value.source_type==='pod')podImageTemplate.value=rows.map(x=>x.key);else imageSelections.value={...imageSelections.value,[imageProduct.value.id]:rows.map(x=>x.id)};pricePreview.value=[]}
function moveImage(index:number,offset:number){const next=index+offset;if(next<0||next>=imageRows.value.length)return;const rows=[...imageRows.value];[rows[index],rows[next]]=[rows[next],rows[index]];imageRows.value=rows;syncImageSelection()}
function makeMain(index:number){const rows=[...imageRows.value];const [row]=rows.splice(index,1);row.included=true;rows.unshift(row);imageRows.value=rows;syncImageSelection()}
function setImageAction(index:number,action:string){if(action==='main')return makeMain(index);imageRows.value[index].included=action!=='exclude';if(action==='additional'&&imageRows.value.findIndex(x=>x.included)===index){const replacement=imageRows.value.findIndex((x,i)=>i!==index&&x.included);if(replacement>=0)return makeMain(replacement)}syncImageSelection()}
function imageAction(index:number){if(!imageRows.value[index].included)return 'exclude';return imageRows.value.findIndex(x=>x.included)===index?'main':'additional'}
watch(()=>podSample.value?.id||individualImageProducts.value[0]?.id,()=>{const sample=podSample.value||individualImageProducts.value[0];if(sample)void editImages(sample);else{imageRequest++;imageProduct.value=undefined;imageRows.value=[];imageLoading.value=false}})
function thumbnailUrl(item:CatalogProduct){const link=item.thumbnail;return link?(link.asset.oss_url||`/api/v1/assets/${link.asset.id}/content`):''}
async function loadRequested(){const ids=[...new Set(String(route.query.products||route.query.product||'').split(',').map(x=>x.trim()).filter(Boolean))];const loaded=await Promise.all(ids.map(async id=>{try{return await api.get<CatalogProduct>(`/catalog/products/${id}`)}catch{return undefined}}));const next={...selected.value};for(const item of loaded)if(item&&item.status==='ready')next[item.id]=item;selected.value=next}
async function load(){await loadRequested();const [storeResult,publicationResult,pricingOptions]=await Promise.all([api.get<any>('/stores'),api.get<any>('/publications?page_size=100'),api.get<any>('/publications/pricing-options')]);pricingModules.value=pricingOptions.modules||[];storePricing.value=pricingOptions.stores||[];stores.value=storeResult.items.filter((x:Store)=>x.platform==='ozon'&&x.enabled);prefixDrafts.value=Object.fromEntries(stores.value.map(x=>[x.id,x.offer_prefix||'']));history.value=publicationResult.items;await loadProducts()}
let categoryRequest=0,categoryTimer:ReturnType<typeof setTimeout>|undefined
async function loadCategories(query='',force=false){
 const storeId=form.store_ids[0];if(!storeId)return ElMessage.warning('先选择至少一家 OZON 店铺')
 const request=++categoryRequest;categoryLoading.value=true
 try{
  if(force){
   const job=await api.post<any>(`/stores/${storeId}/ozon-options/category_tree?refresh=true`,{})
   if(job.job_id){ElMessage.success('类目刷新已交给当前电脑，完成后将保存云端');return}
  }
  const result=await api.get<any>(`/stores/${storeId}/category-options?limit=100&search=${encodeURIComponent(query)}`)
  if(request===categoryRequest)categories.value=result.options||[]
 }catch(error:any){if(request===categoryRequest)ElMessage.warning(error?.message||'请先手动刷新类目')}finally{if(request===categoryRequest)categoryLoading.value=false}
}
watch(()=>form.category_value,value=>{chosenCategory.value=categories.value.find(x=>`${x.description_category_id}:${x.type_id}`===value)})
watch(()=>form.store_ids[0],()=>{categories.value=[];form.category_value='';categoryRequest++})
function searchCategories(query:string){clearTimeout(categoryTimer);categoryTimer=setTimeout(()=>{void loadCategories(query)},250)}
async function readMergeAttributes(storeId:string,category:string,type:string){
  if(!sharedProductsPilot.value)return api.get<any>(`/stores/${storeId}/category-attributes?description_category_id=${category}&type_id=${type}&language=ZH_HANS`)
  const result=await api.post<any>(`/stores/${storeId}/ozon-options/category_attributes?description_category_id=${category}&type_id=${type}`,{})
  if(!result.job_id)return result
  for(let attempt=0;attempt<120;attempt++){
    const job=await api.get<any>(`/jobs/${result.job_id}`)
    if(job.status==='completed')return {items:job.steps?.[0]?.details?.items||[]}
    if(['failed','cancelled'].includes(job.status))throw new Error(job.error_message||'读取变体特征失败')
    await new Promise(resolve=>setTimeout(resolve,1000))
  }
  throw new Error('原电脑尚未完成变体特征读取，请查看任务中心')
}
async function loadCategoryAttributes(){const storeId=form.store_ids[0],parts=String(form.category_value||'').split(':');if(!storeId||parts.length!==2)return ElMessage.warning('请先选择店铺和本批次 Ozon 类目');attributeLoading.value=true;try{const result=await readMergeAttributes(storeId,parts[0]!,parts[1]!);categoryAttributes.value=(result.items||[]).filter((x:any)=>x.id&&x.is_aspect===true&&x.dictionary_id&&!/型号名称/.test(String(x.name||'')));form.variant_attribute_ids=form.variant_attribute_ids.filter((id:number)=>categoryAttributes.value.some((x:any)=>Number(x.id)===id));if(categoryAttributes.value.length)ElMessage.success(`已读取 ${categoryAttributes.value.length} 个可用于合并的变体特征`);else ElMessage.warning('该类目没有返回可用于合并的字典型变体特征')}catch(error:any){ElMessage.error(error?.message||'读取 Ozon 变体特征失败')}finally{attributeLoading.value=false}}
function buildRequirements(){const option=categories.value.find(x=>`${x.description_category_id}:${x.type_id}`===form.category_value)||chosenCategory.value;const keywords=String(form.keywords_text||'').trim();const requirements:any={keywords_reference:keywords,instructions:[form.requirements_text,keywords?`本次关键词参考（可选）：${keywords}。仅选择与真实商品相符的词语，按俄罗斯买家自然语言习惯融入标题、描述和标签；无需全部使用，不堆砌、不逐字照搬，不加入商标、品牌、促销词或未经证实的属性。`:'' ].filter(Boolean).join('\n'),additional_image_count:form.additional_image_count,image_selection:Object.fromEntries(Object.entries(imageSelections.value).filter(([id])=>!!selected.value[id]))};if(podSample.value){if(imageLoading.value)throw new Error('请等待样例图片加载完成');if(!podImageTemplate.value.length||podImageTemplate.value.length>15)throw new Error('POD 上架请选择1至15张图片');if(new Set(podImageTemplate.value).size!==podImageTemplate.value.length)throw new Error('样例图片名称重复，无法统一匹配');requirements.pod_image_template=[...podImageTemplate.value]}if(form.custom_pricing&&form.pricing_mode==='configured')requirements.pricing_overrides=Object.fromEntries(Object.entries(form.pricing_overrides).filter(([,v])=>typeof v==='number'||(typeof v==='string'&&v.trim()!=='')));if(option)Object.assign(requirements,{description_category_id:option.description_category_id,type_id:option.type_id,category_display:option.display});if(form.pricing_mode==='manual'&&form.price)requirements.price=form.price;if(form.pricing_mode==='manual'&&form.old_price)requirements.old_price=form.old_price;return requirements}
async function previewPricing(){if(!selectedProducts.value.length||!form.store_ids.length)return ElMessage.warning('请先选择产品和目标店铺');if(form.pricing_mode==='manual'&&!form.price)return ElMessage.warning('请填写本批次实际售价');previewLoading.value=true;try{const result=await api.post<any>('/publications/preview',{...publicationSelection(),store_ids:form.store_ids,requirements:buildRequirements()});pricePreview.value=result.items||[]}catch(error:any){ElMessage.error(error?.message||'预览失败')}finally{previewLoading.value=false}}
async function publish(){if(!selectedProducts.value.length||!form.store_ids.length)return ElMessage.warning('请选择产品和目标店铺');if(form.pricing_mode==='manual'&&!form.price)return ElMessage.warning('请填写本批次实际售价');if(form.merge_mode==='custom_group'&&(!form.category_value||!form.merge_model_name.trim()||!form.variant_attribute_ids.length))return ElMessage.warning('自定义合并组需要选择类目、填写型号名称并选择变体特征');loading.value=true;try{const result=await api.post<any>('/publications',{...publicationSelection(),store_ids:form.store_ids,requirements:buildRequirements(),image_policy:form.image_policy,custom_regenerate_roles:form.custom_regenerate_roles,save_generated_to_catalog:form.save_generated_to_catalog,generation_provider:form.completion_method==='codex'?'codex':'model',submit_via_api:(form.completion_method==='codex'?form.codex_delivery:form.completion_method)==='api',ozon_merge:{mode:form.merge_mode,model_name:form.merge_model_name,variant_attribute_ids:form.variant_attribute_ids}});ElMessage.success(`已创建 ${result.publication_count} 个 SKU 发布任务`);if(form.completion_method==='codex')codexBatch.value=result.batch_id;clearSelected();pricePreview.value=[];await load()}catch(error:any){ElMessage.error({message:error?.message||'Ozon 发布任务创建失败',duration:8000,showClose:true})}finally{loading.value=false}}
async function show(row:Publication){if((row as any).generation_provider==='codex')openCodex(row);detail.value=await api.get<Publication>(`/publications/${row.id}`);drawer.value=true}
async function retryStore(store:any){await api.post(`/publications/${detail.value!.id}/stores/${store.store_id}/retry`,{});ElMessage.success('已重试该店铺');detail.value=await api.get<Publication>(`/publications/${detail.value!.id}`);await load()}
function statusType(status:string){return ['completed','ready_for_export'].includes(status)?'success':['blocked','failed','import_uncertain'].includes(status)?'danger':['partial','import_pending','stock_pending','promotion_pending'].includes(status)?'warning':'info'}
function imageCount(state:Record<string,unknown>){return Array.isArray(state.images)?state.images.length:0}
onMounted(load)
function openCodex(row:any){codexBatch.value=row.batch_id}
</script>

<template>
  <CodexHandoffPanel v-if="codexBatch" :batch-id="codexBatch" /><div class="page-stack">
  <CatalogOzonTabs />
  <section class="panel"><div class="panel-head"><div><h2>选择要上架的产品</h2><p>按 ERP 发布记录核对店铺：任一 SKU 曾建品即归为已上架；处理中尚未确认建品。筛选不查询平台当前在售状态，已选产品跨页保留。</p></div><el-tag size="large" type="success">已选 {{selectedProducts.length}} 个产品</el-tag></div>
    <div class="toolbar catalog-toolbar"><el-input v-model="search" clearable placeholder="搜索产品名称、产品组或 SKU" @keyup.enter="queryProducts"/><el-select v-model="source" clearable placeholder="全部产品库" @change="changeSource"><el-option label="POD 产品库" value="pod"/><el-option label="跟卖产品库" value="follow"/><el-option label="自主产品库" value="self_selected"/></el-select><el-select v-if="source==='pod'" v-model="podCategory" filterable clearable placeholder="POD 产品类目" @change="queryProducts"><el-option v-for="c in podCategories" :key="c.label" :label="`${c.label}（${c.count}）`" :value="c.label"/></el-select><el-select v-model="filterStore" clearable placeholder="按Ozon店铺核对" @change="changeStoreFilter"><el-option v-for="store in stores" :key="store.id" :label="store.name" :value="store.id"/></el-select><el-select v-model="publicationState" :disabled="!filterStore" placeholder="全部上架状态" clearable @change="queryProducts"><el-option label="可上架（未上架且无进行中任务）" value="available"/><el-option label="尚未上架（含处理中）" value="unlisted"/><el-option label="已上架过该店铺" value="listed"/><el-option label="正在处理" value="processing"/><el-option label="失败待处理" value="failed"/></el-select><el-button type="primary" @click="queryProducts">查询</el-button><span class="grow"/><el-button :disabled="productLoading||bulkSelecting||!products.length" @click="togglePage">{{pageFullySelected?'取消本页':'全选本页'}}（{{products.length}}）</el-button><el-button :loading="bulkSelecting" :disabled="productLoading||!total||total>100" @click="selectAllFiltered">全选筛选结果（{{total}}）</el-button><span v-if="total>100" class="form-tip">每批最多100个，请筛选后分批选择</span><el-button :disabled="bulkSelecting||!selectedProducts.length" @click="clearSelected">清空已选</el-button></div>
    <div v-loading="productLoading" class="publish-product-grid"><article v-for="item in products" :key="item.id" class="publish-product-card" :class="{selected:!!selected[item.id]}" @click="toggleProduct(item)"><div class="publish-card-image"><el-image v-if="thumbnailUrl(item)" :src="thumbnailUrl(item)" fit="cover" lazy/><div v-else class="publish-no-image">暂无图片</div><span class="select-mark">{{selected[item.id]?'✓':'+'}}</span><el-tag class="source-mark" size="small">{{sourceLabel[item.source_type]}}</el-tag></div><div class="publish-card-body"><h3>{{item.name||'未命名产品'}}</h3><div class="product-code mono">{{item.group_code}}</div><div class="sku-section"><b>全部 SKU（{{item.variant_skus?.length||item.variant_count}}）</b><span v-for="sku in item.variant_skus||[item.sku]" :key="sku" class="full-sku mono">{{sku}}</span></div><div class="card-category">{{item.category_display||'尚未选择 Ozon 类目'}}</div><div class="card-footer"><span>{{item.current_asset_count}} 张图片</span><strong>{{item.purchase_price_cny??'-'}} {{item.currency}}</strong></div></div></article><el-empty v-if="!productLoading&&!products.length" description="没有符合条件的可发布产品"/></div>
    <div class="product-pagination"><span>共 {{total}} 个产品 · {{totalPages}} 页</span><el-pagination v-model:current-page="page" v-model:page-size="pageSize" :total="total" :page-sizes="[25,50,100,200]" layout="sizes, prev, pager, next" @change="loadProducts"/></div>
    <div v-if="selectedProducts.length" class="selected-product-tray"><b>本次已选：</b><el-tag v-for="item in selectedProducts" :key="item.id" closable @close="removeSelected(item.id)">{{item.name}} · {{(item.variant_skus||[item.sku]).join('、')}}</el-tag></div>
  </section>
  <section v-if="selectedProducts.length&&variantOptions.length" class="panel"><div class="panel-head"><div><h2>统一选择本批上架规格</h2><p>只提交勾选的规格，系统匹配每个产品的相同规格；未匹配的变体不提交。</p></div><el-tag>{{selectedVariantIds.length}} 个 SKU</el-tag></div><div class="panel-body"><el-checkbox-group v-model="selectedVariantKeys" @change="pricePreview=[]"><el-checkbox v-for="option in variantOptions" :key="option.key" :value="option.key" border><b>{{option.label}}</b> {{option.color}} · 覆盖 {{option.matched}} / {{selectedProducts.length}} 个产品</el-checkbox></el-checkbox-group></div></section>
  <section v-if="selectedProducts.length" class="panel"><div class="panel-head"><div><h2>统一设置上架图片顺序</h2><p>POD 只展示一个样例，图片选用与顺序自动应用到其他所选 POD 产品；每个产品使用自己的图片。第一张启用图片为主图，最多15张，生产印刷原图不进入上架图库。</p></div><el-tag>{{imageRows.filter(x=>x.included).length}} 张启用</el-tag></div><div class="image-selection-body"><p class="image-sample-label" v-if="podSample">POD 样例：{{podSample.sku}}<el-button v-if="imageProduct?.id!==podSample.id" link @click="editImages(podSample)">展示样例图片</el-button></p><div v-if="individualImageProducts.length" class="toolbar"><el-button v-for="item in individualImageProducts" :key="item.id" :type="imageProduct?.id===item.id?'primary':'default'" @click="editImages(item)">{{item.sku}}</el-button></div><p v-if="imageProduct&&imageProduct.source_type!=='pod'">当前产品：{{imageProduct.sku}}（仅修改该产品图片）</p><div v-loading="imageLoading" class="image-rule-grid"><article v-for="(row,index) in imageRows" :key="row.id" class="image-rule-card" :class="{excluded:!row.included,main:imageAction(index)==='main'}"><el-image :src="row.url" fit="cover" :preview-src-list="[row.url]" preview-teleported/><span class="image-rule-index">{{row.included?imageRows.slice(0,index+1).filter(x=>x.included).length:'不用'}}</span><b>{{imageAction(index)==='main'?'主图':row.included?'附图':'不上架'}}</b><small :title="row.name">{{row.key||row.name}}</small><el-segmented :model-value="imageAction(index)" :options="[{label:'主图',value:'main'},{label:'附图',value:'additional'},{label:'不用',value:'exclude'}]" @change="setImageAction(index,String($event))"/><div><el-button size="small" :disabled="index===0" @click="moveImage(index,-1)">前移</el-button><el-button size="small" :disabled="index===imageRows.length-1" @click="moveImage(index,1)">后移</el-button></div></article><el-empty v-if="!imageLoading&&!imageRows.length" description="当前产品没有可上架的 OSS 展示图片"/></div><p class="form-tip">选择与排序即时生效，无需另开页面或点击保存。</p></div></section>
  <section class="panel"><div class="panel-head"><div><h2>本批次上架设置</h2><p>每个选中 SKU、每家店铺生成独立 Offer ID 和发布记录。</p></div></div><div class="panel-body"><el-alert title="尺寸、重量、成本和 SKU 只读取产品库；AI 仅生成文案、属性建议及按策略生成图片。" type="info" :closable="false" show-icon/><el-form label-width="150" class="publication-form">
    <el-form-item label="目标 OZON 店铺"><el-select v-model="form.store_ids" multiple placeholder="选择一家或多家店铺" style="width:100%"><el-option v-for="s in stores" :key="s.id" :value="s.id" :label="`${s.name}（Offer ID 前缀：${s.offer_prefix||'无'}）`"/></el-select></el-form-item>
    <el-form-item label="店铺 Offer ID 前缀"><div style="width:100%"><div v-for="store in targetStores" :key="store.id" class="prefix-row"><b>{{store.name}}</b><el-input v-model="prefixDrafts[store.id]" maxlength="60" :disabled="!canManage" placeholder="无前缀，使用原SKU" style="max-width:230px"/><el-button v-if="canManage" :loading="prefixSaving===store.id" @click="savePrefix(store)">保存店铺前缀</el-button><span>当前示例：{{store.offer_prefix}}{{selectedProducts[0]?.sku||'ERP-SKU'}}</span></div><p v-if="!targetStores.length">选择目标店铺后显示前缀。</p><p class="form-tip">前缀保存为店铺默认值，填写的分隔符原样保留；已有发布记录的 Offer ID 保持不变。{{canManage?'':'由管理员修改店铺默认配置。'}}</p><RouterLink to="/configuration">打开系统配置</RouterLink><span v-if="canManage"> · <RouterLink to="/stores">店铺管理</RouterLink></span></div></el-form-item>
    <el-form-item label="OZON 实时类目"><el-select v-model="form.category_value" filterable remote :remote-method="searchCategories" @visible-change="(open:boolean)=>open&&loadCategories()" clearable :loading="categoryLoading" placeholder="产品库已有类目时可不选" style="flex:1"><el-option v-for="c in categories" :key="`${c.description_category_id}:${c.type_id}`" :label="c.display" :value="`${c.description_category_id}:${c.type_id}`"/></el-select><el-button :loading="categoryLoading" @click="loadCategories('',true)">刷新平台类目</el-button></el-form-item>
    <el-form-item label="商品卡合并方式"><el-radio-group v-model="form.merge_mode"><el-radio-button value="single">单品单链接</el-radio-button><el-radio-button value="custom_group">自定义合并组</el-radio-button></el-radio-group><span class="form-tip">不会按每 30 个产品自动合并。</span></el-form-item>
    <template v-if="form.merge_mode==='custom_group'"><el-alert class="merge-alert" title="同组所有 SKU 使用相同型号名称；这里只展示 Ozon 模板中蓝色“变体特征”分组的字段，不展示品牌、材质等普通商品属性。" type="warning" :closable="false" show-icon/><el-form-item label="合并型号名称"><el-input v-model="form.merge_model_name" maxlength="500" show-word-limit placeholder="例如：本批浴帘系列 2026-09"/></el-form-item><el-form-item label="用于合并的特征"><el-select v-model="form.variant_attribute_ids" multiple filterable :loading="attributeLoading" placeholder="选择商品颜色、颜色名称等变体特征" style="flex:1"><el-option v-for="a in categoryAttributes" :key="a.id" :value="Number(a.id)" :label="`${a.name}${a.is_collection?'（可多选）':''}`"/></el-select><el-button @click="loadCategoryAttributes">读取变体特征</el-button></el-form-item><el-form-item label="自动分配规则"><div class="merge-rule"><b>颜色承担虚拟去重</b><span>类目有商品颜色时，只允许颜色使用 Ozon 合法字典值补位；支持“黑色;白色”等多值组合。</span><b>其他字段保持真实</b><span>尺寸、数量等只读取产品真实资料，缺失时不虚构。只有类目没有颜色变体时，才使用第一个选定特征作为备用虚拟轴。</span></div></el-form-item></template>
    <el-form-item label="本次关键词参考"><el-input v-model="form.keywords_text" type="textarea" :rows="2" :maxlength="2000" show-word-limit placeholder="可留空；填写中文或俄文关键词，多个词可用逗号或换行分隔"/><span class="form-tip">模型按商品事实自行选用，自然融入标题、描述和标签，不要求全部使用。</span></el-form-item>
    <el-form-item label="本次要求"><el-input v-model="form.requirements_text" type="textarea" :rows="3" placeholder="文案重点、禁用表达等"/></el-form-item><el-form-item label="图片策略"><el-radio-group v-model="form.image_policy"><el-radio-button v-for="p in imagePolicies" :key="p[0]" :value="p[0]">{{p[1]}}</el-radio-button></el-radio-group></el-form-item><el-form-item v-if="form.image_policy==='custom'" label="自定义重做"><el-checkbox-group v-model="form.custom_regenerate_roles"><el-checkbox value="main">主图</el-checkbox><el-checkbox value="additional">附图</el-checkbox></el-checkbox-group></el-form-item><el-form-item v-if="['regenerate_additional','regenerate_all'].includes(form.image_policy)||(form.image_policy==='custom'&&form.custom_regenerate_roles.includes('additional'))" label="新附图数量"><el-input-number v-model="form.additional_image_count" :min="1" :max="6"/></el-form-item><el-form-item label="产品库图库"><el-switch v-model="form.save_generated_to_catalog" :disabled="!canSaveGallery"/><span class="form-tip">写回时只能选择一家店。</span></el-form-item>
    <el-form-item label="定价方式"><el-radio-group v-model="form.pricing_mode" @change="pricePreview=[]"><el-radio-button value="configured">按店铺策略自动反算</el-radio-button><el-radio-button value="manual">本批次统一指定</el-radio-button></el-radio-group></el-form-item><el-form-item v-if="form.pricing_mode==='manual'" label="本批次价格"><el-input-number v-model="form.price" :min="1" :precision="2" controls-position="right" placeholder="实际售价" style="width:210px"/><span>CNY 实际售价</span><el-input-number v-model="form.old_price" :min="1" :precision="2" controls-position="right" placeholder="划线价" style="width:210px"/><span>CNY 划线价</span></el-form-item><el-form-item v-else label="自动定价说明"><span class="pricing-explanation">根据每个 SKU 的拿货价、包装尺寸和重量，结合目标利润、贴单、运营、退货、物流服务及店铺倍率反算；下方预览会展示实际采用的参数。</span></el-form-item><template v-if="form.pricing_mode==='configured'"><el-form-item label="本批次自定义参数"><el-switch v-model="form.custom_pricing" @change="pricePreview=[]"/><span class="form-tip">仅作用于本批次，不更改店铺默认策略；留空沿用该店铺参数。</span></el-form-item><el-form-item v-if="form.custom_pricing" label="利润计费模块"><el-select v-model="form.pricing_overrides.pricing_category_module" clearable placeholder="沿用店铺；缺失时必须选择" @change="form.pricing_overrides.pricing_product_category=undefined;pricePreview=[]"><el-option v-for="module in pricingModules" :key="module.name" :value="module.name" :label="module.name"/></el-select><span class="form-tip">原有：{{originalPricing('pricing_category_module')}}</span></el-form-item><el-form-item v-if="form.custom_pricing" label="利润计费商品类目"><el-select v-model="form.pricing_overrides.pricing_product_category" clearable :disabled="!form.pricing_overrides.pricing_category_module" placeholder="选择对应商品类目" @change="pricePreview=[]"><el-option v-for="category in profitCategories" :key="category.name" :value="category.name" :label="category.name"/></el-select><span class="form-tip">原有：{{originalPricing('pricing_product_category')}}。沿用原ERP佣金计费表，与上方商品发布类目分别设置。</span></el-form-item><el-form-item v-for="field in (form.custom_pricing?pricingFields:[])" :key="field[0]" :label="field[1]"><el-input-number v-model="form.pricing_overrides[field[0]]" :min="field[0].includes('multiplier')?0.01:0" :max="field[2]" :precision="2" placeholder="沿用店铺参数" @change="pricePreview=[]"/><span class="form-tip">原有：{{originalPricing(field[0])}}</span></el-form-item></template><el-form-item label="提交前核对"><el-button type="success" plain :loading="previewLoading" :disabled="!selectedProducts.length||!form.store_ids.length" @click="previewPricing">刷新定价与资料预览</el-button><span class="form-tip">不会调用 AI，也不会提交 Ozon。</span></el-form-item>
    <div v-if="pricePreview.length" class="price-preview"><div class="preview-head"><div><h3>逐 SKU · 逐店铺预览</h3><p>这里显示任务真正采用的价格来源和上架前缺失项。</p></div><el-tag :type="pricePreview.some(x=>x.missing.length||x.pricing_error)?'danger':'success'">{{pricePreview.some(x=>x.missing.length||x.pricing_error)?'存在阻塞项':'资料可进入发布流程'}}</el-tag></div><el-table :data="pricePreview" border><el-table-column label="产品 / SKU" min-width="230"><template #default="{row}"><b>{{row.product_name}}</b><small class="table-sub mono">{{row.sku}}</small></template></el-table-column><el-table-column label="店铺 / Offer ID" min-width="200"><template #default="{row}"><b>{{row.store_name}}</b><small class="table-sub mono">{{row.offer_id}}</small></template></el-table-column><el-table-column label="成本依据" width="175"><template #default="{row}">{{row.purchase_price_cny??'-'}} CNY<small class="table-sub">{{row.package.weight_g}}g · {{row.package.length_mm}}×{{row.package.width_mm}}×{{row.package.height_mm}}mm</small><small v-if="row.package.dimensions_source==='virtual_follow_30x20x10cm'" class="virtual-size">跟卖虚拟尺寸 30×20×10cm</small></template></el-table-column><el-table-column label="实际售价" width="135"><template #default="{row}"><b v-if="row.pricing">{{row.pricing.price}} CNY</b><span v-else class="danger-copy">无法计算</span><small v-if="row.pricing" class="table-sub">{{row.pricing?.source==='manual_requirement'?'本批手动指定':row.pricing?.source==='batch_pricing'?'本批参数反算':'店铺策略反算'}}</small></template></el-table-column><el-table-column label="划线价 / 活动参考" width="175"><template #default="{row}"><span v-if="row.pricing">{{row.pricing.old_price}} / {{row.pricing.action_price||'-'}} CNY</span></template></el-table-column><el-table-column label="定价参数" min-width="230"><template #default="{row}"><span v-if="row.pricing?.source==='manual_requirement'">人工指定，不使用策略公式</span><span v-else>{{row.pricing_profile.category_module}} / {{row.pricing_profile.product_category}} · 目标成本利润率 {{row.pricing_profile.target_cost_profit_margin}}% · 广告占比 {{row.pricing_profile.advertising_rate}}% · 退货率 {{row.pricing_profile.return_rate}}% · 售价倍率 {{row.pricing_profile.price_multiplier}} · 划线价倍率 {{row.pricing_profile.old_price_multiplier}}</span></template></el-table-column><el-table-column label="资料检查" min-width="180"><template #default="{row}"><el-tag v-if="!row.missing.length&&!row.pricing_error" type="success">通过</el-tag><span v-else class="danger-copy">{{[...row.missing,row.pricing_error].filter(Boolean).join('；')}}</span><small class="table-sub">{{row.image_count}} 张 OSS 图片</small></template></el-table-column></el-table></div>
    <el-form-item label="完成方式"><el-radio-group v-model="form.completion_method"><el-radio value="api">Seller API 自动提交</el-radio><el-radio value="excel">生成发布包并导出 Excel</el-radio><el-radio value="codex">Codex 接手文案与生图</el-radio></el-radio-group></el-form-item><el-form-item v-if="form.completion_method==='codex'" label="接手后交付"><el-radio-group v-model="form.codex_delivery"><el-radio value="api">审核后 Seller API 提交</el-radio><el-radio value="excel">导出 Excel</el-radio></el-radio-group><span class="form-tip">等待 Codex 生成，不调用原文案和生图模型；主图沿用原 ERP 的3:4俄文商业海报规则（标题、真实卖点、分层构图），生成图片仍需人工核验。</span></el-form-item><el-form-item><el-button type="primary" size="large" :disabled="!selectedProducts.length||attributeLoading||imageLoading" :loading="loading" @click="publish">{{loading?'正在读取 Ozon 字典并创建任务…':form.completion_method==='codex'?'创建 Codex 接管任务':form.completion_method==='api'?'提交所选产品到 OZON':'生成所选产品发布包'}}</el-button><span v-if="form.merge_mode==='custom_group'" class="form-tip">首次提交会先读取所选变体特征的 Ozon 合法值，成功后立即生成后台任务。</span></el-form-item>
  </el-form></div></section>
  <section class="panel"><div class="panel-head"><div><h2>最近上架记录</h2><p>API建品成功后进入待添加库存；Excel导出不会再次调用 AI。</p></div><el-button @click="load">刷新</el-button></div><el-table :data="history" @row-click="show"><el-table-column label="产品 / SKU" min-width="260"><template #default="{row}"><b>{{row.product_name}}</b><small class="table-sub mono">{{row.sku}}</small></template></el-table-column><el-table-column label="店铺" min-width="190"><template #default="{row}">{{row.stores.map((x:any)=>x.store_name).join('、')}}</template></el-table-column><el-table-column label="状态" width="150"><template #default="{row}"><el-tag :type="statusType(row.status)">{{row.status}}</el-tag></template></el-table-column><el-table-column label="操作" width="220"><template #default="{row}"><el-button link type="primary" @click.stop="show(row)">详情</el-button><a class="el-button is-link" :href="`/api/v1/publications/${row.id}/export/ozon.xlsx`" @click.stop>导出 Excel</a><RouterLink v-if="row.job_id" :to="`/jobs?job=${row.job_id}`" @click.stop>任务</RouterLink></template></el-table-column></el-table></section>
  <el-drawer v-model="drawer" size="72%" title="发布包与店铺状态"><template v-if="detail"><el-descriptions :column="3" border><el-descriptions-item label="批次">{{detail.batch_id}}</el-descriptions-item><el-descriptions-item label="SKU">{{detail.sku}}</el-descriptions-item><el-descriptions-item label="状态">{{detail.status}}</el-descriptions-item></el-descriptions><div v-for="store in detail.stores" :key="store.id" class="publication-store-card"><div class="panel-head"><div><strong>{{store.store_name}}</strong><small>{{store.offer_id}}</small></div><div><el-tag :type="statusType(store.status)">{{store.status}}</el-tag><el-button v-if="!['completed','ready_for_export','stock_pending','promotion_pending'].includes(store.status)" link type="primary" @click="retryStore(store)">单店重试</el-button></div></div><div class="panel-body"><p><b>俄文标题：</b>{{store.content.title||'尚未生成'}}</p><p><b>图片：</b>{{store.assets.primary_image?'主图 1 张':'无主图'}}，附图 {{imageCount(store.assets)}} 张</p><p><b>OZON任务：</b>{{store.external_task_id||'-'}}　<b>商品ID：</b>{{store.external_product_id||'-'}}</p><p v-if="store.last_error" class="danger-copy">{{store.last_error}}</p></div></div></template></el-drawer>
</div></template>

<style scoped>.image-sample-label{padding:0 20px;margin:12px 0 0}.image-selection-body>.form-tip{padding:0 20px 15px}.image-selection-body>.toolbar{padding:0 20px}.prefix-row{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:8px 0}.image-rule-grid {
