}
.merge-alert{margin:4px 0 18px}.merge-rule{display:grid;grid-template-columns:100px 1fr;gap:8px 14px;padding:13px 16px;border-radius:9px;background:#fff8e8;color:#66542d;line-height:1.6}.selected-product-tray{display:flex;gap:8px;flex-wrap:wrap;align-items:center;padding:14px 18px;border-top:1px solid #e7edf5}.selected-product-tray .el-tag{max-width:100%;height:auto;min-height:24px;white-space:normal}.product-pagination{display:flex;justify-content:space-between;align-items:center;padding:14px 18px}.publish-product-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(245px,1fr));gap:16px;padding:18px;min-height:220px;background:#f6f8fb}.publish-product-card{overflow:hidden;border:2px solid transparent;border-radius:13px;background:#fff;box-shadow:0 3px 12px rgba(28,50,78,.08);cursor:pointer;transition:.18s}.publish-product-card:hover{transform:translateY(-2px);box-shadow:0 8px 20px rgba(28,50,78,.13)}.publish-product-card.selected{border-color:#2b70c9;box-shadow:0 0 0 3px rgba(43,112,201,.12)}.publish-card-image{position:relative;aspect-ratio:4/3;background:#edf1f6}.publish-card-image .el-image{width:100%;height:100%;display:block}.publish-no-image{height:100%;display:grid;place-items:center;color:#8996a8}.select-mark{position:absolute;right:10px;top:10px;width:30px;height:30px;display:grid;place-items:center;border-radius:50%;color:#2568b8;background:#fff;font-size:20px;font-weight:800;box-shadow:0 2px 8px rgba(0,0,0,.18)}.selected .select-mark{color:#fff;background:#2568b8}.source-mark{position:absolute;left:10px;top:10px}.publish-card-body{padding:14px}.publish-card-body h3{margin:0 0 6px;color:#193553;font-size:16px;line-height:1.4}.product-code{color:#7a889a;font-size:12px}.sku-section{display:flex;flex-direction:column;gap:5px;margin:13px 0;padding:10px;border-radius:8px;background:#f4f7fb}.sku-section b{color:#53657a;font-size:12px}.full-sku{overflow-wrap:anywhere;color:#162f4c;font-size:12px}.card-category{min-height:38px;color:#65758a;font-size:12px;line-height:1.55}.card-footer{display:flex;justify-content:space-between;margin-top:10px;padding-top:10px;border-top:1px solid #edf0f4;color:#718096;font-size:12px}.card-footer strong{color:#193b64}.pricing-explanation{color:#596b80;line-height:1.65}.price-preview{margin:8px 0 22px;padding:16px;border:1px solid #dce6f2;border-radius:10px;background:#f8fbff}.preview-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:13px}.preview-head h3{margin:0;color:#203e62}.preview-head p{margin:4px 0 0;color:#718096;font-size:12px}.virtual-size{display:block;margin-top:3px;color:#b56a16;font-size:11px}@media(max-width:650px){.publish-product-grid{grid-template-columns:1fr}.product-pagination{align-items:flex-start;gap:10px;flex-direction:column}.merge-rule{grid-template-columns:1fr}}</style>
